// Surface a degraded run so it is visible in the execution log rather than
// looking identical to a clean one. The API returns 200 for a full run and
// 207 when at least one source failed.
const res = $input.first().json;
const status = res.statusCode ?? 200;
const body = res.body ?? res;
const results = body.results ?? [];

const failed = results.filter((r) => !r.ok);
const summary = results
  .map((r) => `${r.source}: ${r.ok ? r.observationsWritten + ' obs' : 'FAILED — ' + r.error}`)
  .join('; ');

if (status === 207 || failed.length > 0) {
  console.warn('Lumen ingest degraded — ' + summary);
}

return [{ json: { status, degraded: failed.length > 0, summary, results } }];
